// Ask Cozy Cross-Domain Interaction Rollout FRD, Phase 0 (§21 "Executable
// operation and interaction coverage audit"). Generated from
// ASK_OPERATION_DEFINITIONS and ASK_DOMAIN_COMMAND_REGISTRY, not hand-authored,
// to keep track/rollClass/canonicalOwner/roleFloor/confirmationCapable in sync
// with the live registries rather than drifting into a document-only inventory
// (FRD §21 Phase 0 exit criterion). See docs/architecture/ASK_COZY_PHASE0_COVERAGE_AUDIT.md
// for the derivation rules behind `rollClass` and the methodology.
//
// Record<AskOperationId, ...> is itself the drift check FRD §21 asks for: a
// newly registered AskOperationId with no entry here fails `tsc` before any
// runtime test can even run. validateAskInteractionCoverageMatrix() below adds
// a second, semantic check that a hand-classified entry hasn't drifted from
// what the registries now say (e.g. an operation gaining a domainCommand entry
// without its rollClass being revisited).
//
// rollClass priority when an operation has more than one true fact about it
// (boundary safety class, domain-command confirmation gate, non-routability):
// BOUNDARY_RESPONSE > CONFIRMED_MUTATION > INTERNAL_CAPTURE > everything else.
// Confirmation-gated takes priority over non-routable because the propose/
// confirm-split CAPTURE_* operations are both non-routable AND
// confirmation-gated -- their real product behavior is the confirmed
// mutation (confirmCapabilityHandlerRegistry.ts), reached through a
// non-message-routed propose-time path. See each entry's `note` for
// operation-specific caveats this priority order glosses over.
//
// Stage 1 (this file, as generated): track, ROLL-001 interaction class,
// canonical owner, role floor, message-routability and confirmation
// capability are fully code-derived (STATIC verification level) for all 77
// operations. Stage 2 (tracked per-track in the audit doc, not yet done):
// current UI surface, typed-dispatch path, freshness/version source,
// idempotency, reconciliation and handoff behavior remain PENDING per
// operation until each track gets its own deeper trace -- ROLL-010 requires
// this to be recorded honestly rather than inferred from a handler's mere
// existence.

import type { AskOperationId } from './askOperationRegistry';
import { ASK_OPERATION_DEFINITIONS } from './askOperationRegistry';
import { ASK_DOMAIN_COMMAND_REGISTRY } from './askDomainCommandRegistry';

export type AskInteractionClass =
  | 'READ_RESULT'
  | 'FILTER_REFINEMENT'
  | 'CONVERSATIONAL_CONTINUATION'
  | 'PROPOSAL'
  | 'CONFIRMED_MUTATION'
  | 'WORKFLOW_CONTINUATION'
  | 'NAVIGATION_HANDOFF'
  | 'PROACTIVE_INSIGHT'
  | 'INTERNAL_CAPTURE'
  | 'BOUNDARY_RESPONSE';

export type AskRolloutTrack =
  | 'Completed reference'
  | 'Records and capture'
  | 'Buyer journey'
  | 'Financial and ownership'
  | 'Protection and claims'
  | 'Decisions and projects'
  | 'Home intelligence and work'
  | 'Household/action utilities'
  | 'Persistent goals'
  | 'Discovery and guidance'
  | 'Boundaries';

export type AskTraceStatus = 'PENDING' | 'TRACED';

export interface AskInteractionCoverageEntry {
  track: AskRolloutTrack;
  /** ROLL-001 classification. STATIC verification (derived from registry semantics this session, not yet product-reviewed). */
  rollClass: AskInteractionClass;
  /** = ASK_OPERATION_DEFINITIONS[op].adapterKey, restated for readability. */
  canonicalOwner: string;
  roleFloor: 'VIEWER' | 'CONTRIBUTOR' | 'OWNER' | null;
  messageRoutable: boolean;
  /** True iff a confirmation-gated write exists in ASK_DOMAIN_COMMAND_REGISTRY for this operation. */
  confirmationCapable: boolean;
  correctionModes: readonly string[];
  /** Operation-specific caveat the priority rule above glosses over. Empty string when none. */
  note: string;
  /** Stage 2 fields -- see file header. All PENDING as of Phase 0 Stage 1. */
  uiSurface: { status: AskTraceStatus; notes: string };
  freshnessSource: { status: AskTraceStatus; notes: string };
  idempotency: { status: AskTraceStatus; notes: string };
  reconciliation: { status: AskTraceStatus; notes: string };
  handoff: { status: AskTraceStatus; notes: string };
}

